function action_start(string $action,string $class='',string $target=''): void {echo '<form method="post" action="'.h($target?:'/'). '" class="'.h($class).'">';csrf_field();if($action==='cart_add')echo '<span class="product-cart-quantity" data-product-count aria-live="polite"></span>';echo '<input type="hidden" name="action" value="'.h($action).'">';}
function hidden(string $name,mixed $value): void {echo '<input type="hidden" name="'.h($name).'" value="'.h($value).'">';}
function product_card(array $p,string $context=''): void {$wholesaleView=$context==='wholesale';$explicitWholesale=is_wholesale_product($p);?><article class="product-card"><a class="product-image" href="/products/<?=h($p['slug'])?>"><span class="product-badge"><?=$wholesaleView||$explicitWholesale?'محصول عمده':'محصول خرده'?></span><img src="<?=h(display_image($p['image']))?>" alt="<?=h($p['name'])?>؛ <?=h($p['category_name']??'محصولات پلاستیکی')?>" width="350" height="280" loading="lazy" decoding="async" sizes="(max-width: 560px) 46vw, (max-width: 900px) 44vw, 350px"></a><div class="product-body"><span class="muted product-category"><?=h($p['category_name']??'محصولات')?></span><a href="/products/<?=h($p['slug'])?>"><h3><?=h($p['name'])?></h3></a><div class="product-meta"><span><?=$p['stock']?'موجود در انبار':'ناموجود'?></span><span>هر <?=h($wholesaleView||$explicitWholesale?'کیلوگرم':$p['unit'])?></span></div><div class="product-bottom"><div><small><?=$wholesaleView||$explicitWholesale?'قیمت عمده هر کیلو':'قیمت خرده'?></small><strong><?=money($wholesaleView?(int)$p['wholesale']:unit_price($p,1))?> <span>تومان</span></strong></div><?php if($wholesaleView||$explicitWholesale):?><a class="btn outline" href="/products/<?=h($p['slug'])?>">انتخاب وزن</a><?php else:quantity_control($p);endif;?></div><div class="wholesale-hint"><?php if($wholesaleView||$explicitWholesale):?>وزن پیشنهادی اولیه ۲۵ کیلوگرم است؛ وزن و مبلغ نهایی را در صفحه محصول انتخاب کنید.<?php else:product_sales_hint($p);endif;?></div></div></article><?php }
