function quantity_control(array $p,bool $initialButton=false,bool $productDetail=false): void {
 $qty=(int)($_SESSION['cart'][$p['id']]??0);$max=min(1000,(int)$p['stock']);
 if($productDetail&&is_wholesale_product($p)){
  $selected=$qty?:min(25,max(1,$max));$tiers=wholesale_price_tiers($p);$active=wholesale_tier_for_quantity($p,$selected);$tierData=h(json_encode(['min2'=>$tiers['tier_2_min'],'min3'=>$tiers['tier_3_min'],'min4'=>$tiers['tier_4_min'],'prices'=>[$tiers['price_1'],$tiers['price_2'],$tiers['price_3'],$tiers['price_4']]],JSON_UNESCAPED_UNICODE));?>
  <form method="post" action="/" class="quantity-control wholesale-quantity-control" data-quantity-control data-wholesale-selector data-tier-config="<?=$tierData?>" data-max="<?=$max?>" data-qty="<?=$qty?>"><?php csrf_field();hidden('id',$p['id']);hidden('quantity',1);?><input type="hidden" name="requested_quantity" value="<?=$selected?>" data-wholesale-quantity>
  <div class="wholesale-selection-head"><strong>مقدار سفارش</strong><span>واحد محاسبه: کیلوگرم</span></div><div class="quantity-stepper" role="group" aria-label="انتخاب وزن <?=h($p['name'])?>"><button type="button" data-wholesale-minus aria-label="یک کیلو کاهش" <?=$selected<=1?'disabled':''?>>−</button><output data-product-count data-wholesale-count aria-live="polite"><?=money($selected)?> کیلو</output><button type="button" data-wholesale-plus aria-label="یک کیلو افزایش" <?=$selected>=$max?'disabled':''?>>+</button></div><div class="quantity-presets" role="group" aria-label="افزودن سریع وزن"><span>افزودن سریع:</span><?php foreach([1,2,5,10,25,50] as $amount):?><button type="button" data-wholesale-preset="<?=$amount?>">+<?=money($amount)?></button><?php endforeach;?></div>
  <div class="wholesale-calculation" aria-live="polite"><p><span>قیمت هر کیلو</span><strong data-wholesale-unit-price><?=money($active['price'])?> تومان</strong></p><p><span>محاسبه مبلغ</span><strong><b data-wholesale-formula><?=money($selected)?> × <?=money($active['price'])?></b> تومان</strong></p><p class="wholesale-total"><span>مبلغ کل</span><strong data-wholesale-total><?=money($selected*$active['price'])?> تومان</strong></p><small data-wholesale-range>سفارش شما با قیمت بازه <?=money($active['min'])?><?=$active['max']?' تا '.money($active['max']).' کیلو':' کیلو و بیشتر'?> محاسبه می‌شود.</small></div>
  <button type="submit" name="action" value="cart_set" class="btn wholesale-add" <?=$max?'':'disabled'?>><?=$qty?'به‌روزرسانی سبد خرید':'افزودن به سبد خرید'?></button><span data-cart-message role="status"></span></form><?php return;
 }
 ?><form method="post" action="/" class="quantity-control" data-quantity-control data-max="<?=$max?>" data-qty="<?=$qty?>">
 <?php csrf_field();hidden('id',$p['id']);hidden('quantity',1);?>
 <?php if($initialButton):?><button type="submit" name="action" value="cart_add" class="btn" data-first-add data-add-quantity="1" <?=$qty?'hidden':''?> <?=$max>0?'':'disabled'?>><?=$max>0?'افزودن به سبد خرید':'ناموجود'?></button><?php endif;?>
 <div class="quantity-stepper" <?=$initialButton&&$qty===0?'hidden':''?> role="group" aria-label="تعداد <?=h($p['name'])?>">
 <button type="submit" name="action" value="cart_decrease" data-minus aria-label="کاهش تعداد <?=h($p['name'])?>" <?=$qty?'':'disabled'?>>−</button>
 <output data-product-count aria-live="polite" aria-label="تعداد انتخاب‌شده"><?=money($qty)?></output>
 <button type="submit" name="action" value="cart_add" data-plus data-add-quantity="1" aria-label="افزایش تعداد <?=h($p['name'])?>" <?=$qty<$max?'':'disabled'?>>+</button>
 </div><small data-current-price>قیمت فعلی هر <?=h($p['unit'])?>: <?=money(unit_price($p,max(1,$qty)))?> تومان</small><span data-cart-message role="status"></span></form><?php wholesale_recommendation($p,$qty);
}
